#!/bin/zsh
# 让 Codex 出 iPhone 版「灵动岛 + 锁屏实时活动 + 控制中心一键录音」的设计稿，对应 Mac 的刘海快捷面板。
cd "$(dirname "$0")"
name=ui_island
[ -f "$name.png" ] && exit 0
P="当前目录有 ui_notch.png（豆仓 Mac 版已定稿的刘海快捷面板：纯黑面板、玫瑰红 #F43F5E 小胶囊按钮、绿色只表示已连接）、ref_mascot2.png（吉祥物小豆）和 ios_home_list.png（豆仓 iPhone 版的界面风格）。请先看这三张图，然后使用内置的 image_gen 工具（把它们一起传入）生成一张 16:10 横向的高保真设计稿，并排展示四台 iPhone 17 Pro 屏幕（正视图、不要透视、浅暖灰背景），每台下面一行小标题：① 「灵动岛 · 录音中」：手机桌面，顶部灵动岛收起状态，左边一个红色小圆点和「12:48」计时，右边一小段跳动的玫瑰红声波；② 「灵动岛 · 长按展开」：灵动岛展开成黑色圆角大块，左上小豆头像和「soundcore Work · 正在录音」，中间大号白色计时「12:48」，下面两个小胶囊按钮「⏸ 暂停」（深灰）和「■ 结束」（玫瑰红），和 Mac 刘海面板同样的按钮尺寸和风格；③ 「锁屏 · 实时活动」：锁屏界面下方一条黑色半透明圆角卡片，左边小豆头像，中间「豆仓 · 正在录音 12:48」和一小段声波，右边两个圆形小按钮（暂停、结束）；④ 「控制中心 · 一键录音」：控制中心里一个圆形按钮控件，玫瑰红圆点图标，下面小字「豆仓录音」，旁边还有一个「用手机录」的控件。整体克制、高级，苹果原生风格。界面文字全部是简体中文，像苹方，清晰可读、没有乱码。绝对不要蓝色、紫色、琥珀橙。生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。"
t0=$(date +%s)
codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write "$P" < /dev/null > "$name.log" 2>&1
echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
